def candy(ratings):
    n, c = len(ratings), [1] * len(ratings)
    changed = True
    while changed:
        changed = False
        for i in range(n):
            if i > 0 and ratings[i] > ratings[i - 1] and c[i] <= c[i - 1]:
                c[i] = c[i - 1] + 1; changed = True
            if i < n - 1 and ratings[i] > ratings[i + 1] and c[i] <= c[i + 1]:
                c[i] = c[i + 1] + 1; changed = True
    return sum(c)

def candy(ratings):
    n = len(ratings)
    c = [1] * n
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            c[i] = c[i - 1] + 1
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            c[i] = max(c[i], c[i + 1] + 1)
    return sum(c)

def candy(ratings):
    n = len(ratings)
    if n == 1:
        return 1
    total, up, down, peak = 1, 0, 0, 0
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            up += 1; down = 0; peak = up
            total += up + 1
        elif ratings[i] == ratings[i - 1]:
            up = down = peak = 0
            total += 1
        else:
            up = 0; down += 1
            total += down + (0 if down <= peak else 1)   # the peak may need to grow
    return total
